// Passo 1: conferimos que veio uma lista de verdade.
function formarFrase(palavras) {
  if (!Array.isArray(palavras)) {
    throw new Error('palavras precisa ser uma lista');
  }

  // Passo 2: join cola as palavras com um espaço entre elas.
  return palavras.join(' ');
}

console.log(formarFrase(['eu', 'estudo', 'node']));
// imprime: eu estudo node
